/**
 * Class: mxSwimlane
 *
 * Extends <mxShape> to implement a swimlane shape. This shape is registered
 * under <mxConstants.SHAPE_SWIMLANE> in <mxCellRenderer>. Use the
 * <mxConstants.STYLE_STYLE_STARTSIZE> to define the size of the title
 * region, <mxConstants.STYLE_SWIMLANE_FILLCOLOR> for the content area fill,
 * <mxConstants.STYLE_SEPARATORCOLOR> to draw an additional vertical separator
 * and <mxConstants.STYLE_SWIMLANE_LINE> to hide the line between the title
 * region and the content area. The <mxConstants.STYLE_HORIZONTAL> affects
 * the orientation of this shape, not only its label.
 * 
 * Constructor: mxSwimlane
 *
 * Constructs a new swimlane shape.
 * 
 * Parameters:
 * 
 * bounds - <mxRectangle> that defines the bounds. This is stored in
 * <mxShape.bounds>.
 * fill - String that defines the fill color. This is stored in <fill>.
 * stroke - String that defines the stroke color. This is stored in <stroke>.
 * strokewidth - Optional integer that defines the stroke width. Default is
 * 1. This is stored in <strokewidth>.
 */
function mxSwimlane(bounds, fill, stroke, strokewidth)
{
	mxShape.call(this);
	this.bounds = bounds;
	this.fill = fill;
	this.stroke = stroke;
	this.strokewidth = (strokewidth != null) ? strokewidth : 1;
};

/**
 * Extends mxShape.
 */
mxUtils.extend(mxSwimlane, mxShape);

/**
 * Variable: imageSize
 *
 * Default imagewidth and imageheight if an image but no imagewidth
 * and imageheight are defined in the style. Value is 16.
 */
mxSwimlane.prototype.imageSize = 16;

/**
 * Variable: fixedHeaderDefault
 *
 * Default value for the fixedHeader style. If true, the swimlane header is
 * always rendered even when startSize is 0. Subclasses may set this to false
 * so that startSize of 0 falls back to non-swimlane rendering. Default is true.
 */
mxSwimlane.prototype.fixedHeaderDefault = true;

/**
 * Function: apply
 * 
 * Extends mxShape to update the swimlane styles.
 *
 * Parameters:
 *
 * state - <mxCellState> of the corresponding cell.
 */
 mxSwimlane.prototype.apply = function(state)
{
	var old = this.spacing;
	mxShape.prototype.apply.apply(this, arguments);
	
	if (this.style != null)
	{
		this.laneFill = mxUtils.getValue(this.style,
			mxConstants.STYLE_SWIMLANE_FILLCOLOR,
			mxConstants.NONE);
	}
};

/**
 * Function: isRoundable
 * 
 * Adds roundable support.
 */
mxSwimlane.prototype.isRoundable = function()
{
	return true;
};

/**
 * Function: isGlassable
 *
 * Adds glass support for the title area.
 */
mxSwimlane.prototype.isGlassable = function()
{
	return true;
};

/**
 * Function: getTitleSize
 * 
 * Returns the title size.
 */
mxSwimlane.prototype.getTitleSize = function()
{
	return Math.max(0, mxUtils.getValue(this.style,
		mxConstants.STYLE_STARTSIZE,
		mxConstants.DEFAULT_STARTSIZE));
};

/**
 * Function: getFooterSize
 *
 * Returns the size of the footer, the filled and bordered region painted at the
 * end of the swimlane opposite the title. Default is 0 (no footer).
 */
mxSwimlane.prototype.getFooterSize = function()
{
	return Math.max(0, mxUtils.getValue(this.style,
		mxConstants.STYLE_FOOTER_SIZE, 0));
};

/**
 * Function: getLabelBounds
 * 
 * Returns the bounding box for the label.
 */
mxSwimlane.prototype.getLabelBounds = function(rect)
{
	var start = this.getTitleSize();
	var fixedHeader = mxUtils.getValue(this.style,
		mxConstants.STYLE_FIXED_HEADER, this.fixedHeaderDefault);

	if (start == 0 && !fixedHeader)
	{
		return mxShape.prototype.getLabelBounds.apply(this, arguments);
	}

	var flipH = mxUtils.getValue(this.style, mxConstants.STYLE_FLIPH, 0) == 1;
	var flipV = mxUtils.getValue(this.style, mxConstants.STYLE_FLIPV, 0) == 1;
	var bounds = new mxRectangle(rect.x, rect.y, rect.width, rect.height);
	var horizontal = this.isHorizontal();

	// East is default
	var shapeVertical = (this.direction == mxConstants.DIRECTION_NORTH ||
			this.direction == mxConstants.DIRECTION_SOUTH);
	var realHorizontal = horizontal == !shapeVertical;
	var realFlipH = !realHorizontal && flipH !=
		(this.direction == mxConstants.DIRECTION_SOUTH ||
		this.direction == mxConstants.DIRECTION_WEST);
	var realFlipV = realHorizontal && flipV !=
		(this.direction == mxConstants.DIRECTION_SOUTH ||
		this.direction == mxConstants.DIRECTION_WEST);

	// Shape is horizontal
	if (!shapeVertical)
	{
		var tmp = Math.min(bounds.height, start * this.scale);

		if (realFlipH || realFlipV)
		{
			bounds.y += bounds.height - tmp;
		}

		bounds.height = tmp;
	}
	else
	{
		var tmp = Math.min(bounds.width, start * this.scale);
		
		if (realFlipH || realFlipV)
		{
			bounds.x += bounds.width - tmp;	
		}

		bounds.width = tmp;
	}
	
	return bounds;
};

/**
 * Function: getGradientBounds
 * 
 * Returns the bounding box for the gradient box for this shape.
 */
mxSwimlane.prototype.getGradientBounds = function(c, x, y, w, h)
{
	var start = this.getTitleSize();
	
	if (this.isHorizontal())
	{
		return new mxRectangle(x, y, w, Math.min(start, h));
	}
	else
	{
		return new mxRectangle(x, y, Math.min(start, w), h);
	}
};

/**
 * Function: getSwimlaneArcSize
 * 
 * Returns the arcsize for the swimlane.
 */
mxSwimlane.prototype.getSwimlaneArcSize = function(w, h, start)
{
	if (mxUtils.getValue(this.style, mxConstants.STYLE_ABSOLUTE_ARCSIZE, 0) == '1')
	{
		return Math.min(w / 2, Math.min(h / 2, mxUtils.getValue(this.style,
			mxConstants.STYLE_ARCSIZE, mxConstants.LINE_ARCSIZE) / 2));
	}
	else
	{
		var f = mxUtils.getValue(this.style, mxConstants.STYLE_ARCSIZE,
			mxConstants.RECTANGLE_ROUNDING_FACTOR * 100) / 100;

		return start * f * 3; 
	}
};

/**
 * Function: isHorizontal
 *
 * Paints the swimlane vertex shape.
 */
mxSwimlane.prototype.isHorizontal = function()
{
	return mxUtils.getValue(this.style, mxConstants.STYLE_HORIZONTAL, 1) == 1;
};

/**
 * Function: paintVertexShape
 *
 * Paints the swimlane vertex shape.
 */
mxSwimlane.prototype.paintVertexShape = function(c, x, y, w, h)
{
	if (!this.outline)
	{
		var start = this.getTitleSize();
		var fixedHeader = mxUtils.getValue(this.style,
			mxConstants.STYLE_FIXED_HEADER, this.fixedHeaderDefault);

		if (start == 0 && !fixedHeader)
		{
			return;
		}

		var r = 0;
		
		if (this.isHorizontal())
		{
			start = Math.min(start, h);
		}
		else
		{
			start = Math.min(start, w);
		}
		
		c.translate(x, y);
		
		if (!this.isRounded)
		{
			this.paintSwimlane(c, x, y, w, h, start);
		}
		else
		{
			r = this.getSwimlaneArcSize(w, h, start);
			r = Math.min(((this.isHorizontal()) ? h : w) - start, Math.min(start, r));
			this.paintRoundedSwimlane(c, x, y, w, h, start, r);
		}

		this.paintFooter(c, x, y, w, h, start, r);

		var sep = mxUtils.getValue(this.style, mxConstants.STYLE_SEPARATORCOLOR, mxConstants.NONE);
		this.paintSeparator(c, x, y, w, h, start, sep);

		if (this.image != null)
		{
			var bounds = this.getImageBounds(x, y, w, h);
			var clipPath = mxUtils.getValue(this.style, mxConstants.STYLE_CLIP_PATH, null);
			c.image(bounds.x - x, bounds.y - y, bounds.width, bounds.height,
					this.image, false, false, false, clipPath);
		}
		
		if (this.glass)
		{
			c.setShadow(false);

			if (this.isHorizontal())
			{
				this.paintGlassEffect(c, 0, 0, w, start, r);
			}
			else
			{
				this.paintTitleGlassEffect(c, 0, 0, start, h, r,
					mxConstants.DIRECTION_WEST);
			}
		}
	}
};

/**
 * Function: paintTitleGlassEffect
 *
 * Paints the glass effect for the title with the given bounds, where the
 * glass effect starts at the outer side of the title given by side
 * (<mxConstants.DIRECTION_NORTH>, <mxConstants.DIRECTION_EAST>,
 * <mxConstants.DIRECTION_SOUTH> or <mxConstants.DIRECTION_WEST>), as for a
 * rotated horizontal title.
 *
 * The glass effect is painted in a frame along the title (u along the title,
 * v inward from its outer side) and every point is mapped to the given side
 * instead of rotating the canvas, since some canvases (eg. <mxVsdxCanvas2D>)
 * can only rotate the whole shape.
 */
mxSwimlane.prototype.paintTitleGlassEffect = function(c, x, y, w, h, arc, side)
{
	var turns = (side == mxConstants.DIRECTION_EAST) ? 1 :
		((side == mxConstants.DIRECTION_SOUTH) ? 2 :
		((side == mxConstants.DIRECTION_WEST) ? 3 : 0));

	c.save();

	if (turns == 0)
	{
		this.paintGlassEffect(c, x, y, w, h, arc);
	}
	else
	{
		var vertical = turns != 2;
		var tw = (vertical) ? h : w;
		var th = (vertical) ? w : h;
		var dirs = [mxConstants.DIRECTION_NORTH, mxConstants.DIRECTION_EAST,
			mxConstants.DIRECTION_SOUTH, mxConstants.DIRECTION_WEST];

		// Same as rotating (u, v) by 90 degrees times turns around the center
		var mapX = function(u, v)
		{
			return (turns == 1) ? x + w - v : ((turns == 2) ? x + w - u : x + v);
		};

		var mapY = function(u, v)
		{
			return (turns == 1) ? y + u : ((turns == 2) ? y + h - v : y + h - u);
		};

		var mc = {handJiggle: c.handJiggle,
			setGradient: function(color1, color2, gx, gy, gw, gh, direction, alpha1, alpha2)
			{
				var x1 = mapX(gx, gy);
				var y1 = mapY(gx, gy);
				var x2 = mapX(gx + gw, gy + gh);
				var y2 = mapY(gx + gw, gy + gh);
				var index = mxUtils.indexOf(dirs, (direction != null) ?
					direction : mxConstants.DIRECTION_SOUTH);

				c.setGradient(color1, color2, Math.min(x1, x2), Math.min(y1, y2),
					Math.abs(x2 - x1), Math.abs(y2 - y1), (index >= 0) ?
					dirs[(index + turns) % 4] : direction, alpha1, alpha2);
			},
			begin: function()
			{
				c.begin();
			},
			moveTo: function(u, v)
			{
				c.moveTo(mapX(u, v), mapY(u, v));
			},
			lineTo: function(u, v)
			{
				c.lineTo(mapX(u, v), mapY(u, v));
			},
			quadTo: function(u1, v1, u2, v2)
			{
				c.quadTo(mapX(u1, v1), mapY(u1, v1), mapX(u2, v2), mapY(u2, v2));
			},
			curveTo: function(u1, v1, u2, v2, u3, v3)
			{
				c.curveTo(mapX(u1, v1), mapY(u1, v1), mapX(u2, v2),
					mapY(u2, v2), mapX(u3, v3), mapY(u3, v3));
			},
			close: function()
			{
				c.close();
			},
			fill: function()
			{
				c.fill();
			}
		};

		this.paintGlassEffect(mc, 0, 0, tw, th, arc);
	}

	c.restore();
};

/**
 * Function: configurePointerEvents
 *
 * Paints the swimlane vertex shape.
 */
mxSwimlane.prototype.configurePointerEvents = function(c)
{
	var events = true;
	var head = true;
	var body = true;
	
	if (this.style != null)
	{
		events = mxUtils.getValue(this.style, mxConstants.STYLE_POINTER_EVENTS, '1') == '1';
		head = mxUtils.getValue(this.style, mxConstants.STYLE_SWIMLANE_HEAD, 1) == 1;
		body = mxUtils.getValue(this.style, mxConstants.STYLE_SWIMLANE_BODY, 1) == 1;
	}
	if (events || head || body)
	{
		mxShape.prototype.configurePointerEvents.apply(this, arguments);
	}
};

/**
 * Function: paintSwimlane
 *
 * Paints the swimlane vertex shape.
 */
mxSwimlane.prototype.paintSwimlane = function(c, x, y, w, h, start)
{
	var fill = this.laneFill;
	var events = true;
	var line = true;
	var head = true;
	var body = true;
	
	if (this.style != null)
	{
		events = mxUtils.getValue(this.style, mxConstants.STYLE_POINTER_EVENTS, '1') == '1';
		line = mxUtils.getValue(this.style, mxConstants.STYLE_SWIMLANE_LINE, 1) == 1;
		head = mxUtils.getValue(this.style, mxConstants.STYLE_SWIMLANE_HEAD, 1) == 1;
		body = mxUtils.getValue(this.style, mxConstants.STYLE_SWIMLANE_BODY, 1) == 1;
	}

	if (this.isHorizontal())
	{
		c.begin();
		c.moveTo(0, start);
		c.lineTo(0, 0);
		c.lineTo(w, 0);
		c.lineTo(w, start);

		if (head)
		{
			c.fillAndStroke();
		}
		else
		{
			c.fill();
		}

		if (start < h)
		{
			if (fill == mxConstants.NONE || !events)
			{
				c.pointerEvents = false;
			}
			
			if (fill != mxConstants.NONE)
			{
				c.setFillColor(fill);
			}
			
			c.begin();
			c.moveTo(0, start);
			c.lineTo(0, h);
			c.lineTo(w, h);
			c.lineTo(w, start);

			if (body)
			{
				if (fill == mxConstants.NONE)
				{
					c.stroke();
				}
				else if (body)
				{
					c.fillAndStroke();
				}
			}
			else if (fill != mxConstants.NONE)
			{
				c.fill();
			}
		}
	}
	else
	{
		c.begin();
		c.moveTo(start, 0);
		c.lineTo(0, 0);
		c.lineTo(0, h);
		c.lineTo(start, h);

		if (head)
		{
			c.fillAndStroke();
		}
		else
		{
			c.fill();
		}

		if (start < w)
		{
			if (fill == mxConstants.NONE || !events)
			{
				c.pointerEvents = false;
			}
			
			if (fill != mxConstants.NONE)
			{
				c.setFillColor(fill);
			}
			
			c.begin();
			c.moveTo(start, 0);
			c.lineTo(w, 0);
			c.lineTo(w, h);
			c.lineTo(start, h);
			
			if (body)
			{
				if (fill == mxConstants.NONE)
				{
					c.stroke();
				}
				else if (body)
				{
					c.fillAndStroke();
				}
			}
			else if (fill != mxConstants.NONE)
			{
				c.fill();
			}
		}
	}
	
	if (line)
	{
		this.paintDivider(c, x, y, w, h, start, fill == mxConstants.NONE);
	}
};

/**
 * Function: paintRoundedSwimlane
 *
 * Paints the swimlane vertex shape.
 */
mxSwimlane.prototype.paintRoundedSwimlane = function(c, x, y, w, h, start, r)
{
	var fill = this.laneFill;
	var events = true;
	var line = true;
	var head = true;
	var body = true;
	
	if (this.style != null)
	{
		events = mxUtils.getValue(this.style, mxConstants.STYLE_POINTER_EVENTS, '1') == '1';
		line = mxUtils.getValue(this.style, mxConstants.STYLE_SWIMLANE_LINE, 1) == 1;
		head = mxUtils.getValue(this.style, mxConstants.STYLE_SWIMLANE_HEAD, 1) == 1;
		body = mxUtils.getValue(this.style, mxConstants.STYLE_SWIMLANE_BODY, 1) == 1;
	}

	if (this.isHorizontal())
	{
		c.begin();
		c.moveTo(w, start);
		c.lineTo(w, r);
		c.quadTo(w, 0, w - Math.min(w / 2, r), 0);
		c.lineTo(Math.min(w / 2, r), 0);
		c.quadTo(0, 0, 0, r);
		c.lineTo(0, start);

		if (head)
		{
			c.fillAndStroke();
		}
		else
		{
			c.fill();
		}

		if (start < h)
		{
			if (fill == mxConstants.NONE || !events)
			{
				c.pointerEvents = false;
			}
			
			if (fill != mxConstants.NONE)
			{
				c.setFillColor(fill);
			}
			
			c.begin();
			c.moveTo(0, start);
			c.lineTo(0, h - r);
			c.quadTo(0, h, Math.min(w / 2, r), h);
			c.lineTo(w - Math.min(w / 2, r), h);
			c.quadTo(w, h, w, h - r);
			c.lineTo(w, start);
			
			if (body)
			{
				if (fill == mxConstants.NONE)
				{
					c.stroke();
				}
				else if (body)
				{
					c.fillAndStroke();
				}
			}
			else if (fill != mxConstants.NONE)
			{
				c.fill();
			}
		}
	}
	else
	{
		c.begin();
		c.moveTo(start, 0);
		c.lineTo(r, 0);
		c.quadTo(0, 0, 0, Math.min(h / 2, r));
		c.lineTo(0, h - Math.min(h / 2, r));
		c.quadTo(0, h, r, h);
		c.lineTo(start, h);

		if (head)
		{
			c.fillAndStroke();
		}
		else
		{
			c.fill();
		}

		if (start < w)
		{
			if (fill == mxConstants.NONE || !events)
			{
				c.pointerEvents = false;
			}
			
			if (fill != mxConstants.NONE)
			{
				c.setFillColor(fill);
			}
			
			c.begin();
			c.moveTo(start, h);
			c.lineTo(w - r, h);
			c.quadTo(w, h, w, h - Math.min(h / 2, r));
			c.lineTo(w, Math.min(h / 2, r));
			c.quadTo(w, 0, w - r, 0);
			c.lineTo(start, 0);

			if (body)
			{
				if (fill == mxConstants.NONE)
				{
					c.stroke();
				}
				else if (body)
				{
					c.fillAndStroke();
				}
			}
			else if (fill != mxConstants.NONE)
			{
				c.fill();
			}
		}
	}

	if (line)
	{
		this.paintDivider(c, x, y, w, h, start, fill == mxConstants.NONE);
	}
};

/**
 * Function: paintFooter
 *
 * Paints the footer, a filled and bordered region at the end of the swimlane
 * opposite the title. The footer follows the rounded corners of the swimlane
 * when rounded (passing r = 0 for the non-rounded case), tracing the lane wall
 * exactly even when the footer is shorter than the arc radius. Supports both
 * horizontal and vertical orientations.
 */
mxSwimlane.prototype.paintFooter = function(c, x, y, w, h, start, r)
{
	var footer = this.getFooterSize();
	var horizontal = this.isHorizontal();
	var size = (horizontal) ? h : w;

	// Keeps the footer within the body so it never overlaps the title
	footer = Math.min(footer, size - start);

	if (footer <= 0)
	{
		return;
	}

	var fill = this.fill;

	// Reuses the title fill (the body may have switched to the lane fill) and
	// disables the shadow so the inner border does not cast one onto the body
	if (fill != null && fill != mxConstants.NONE)
	{
		c.setFillColor(fill);
	}

	c.setShadow(false);
	c.begin();

	if (horizontal)
	{
		var rr = Math.min(w / 2, r);

		if (footer >= r)
		{
			// Divider clears the corners: straight sides plus the full rounding
			c.moveTo(0, h - footer);
			c.lineTo(0, h - r);
			c.quadTo(0, h, rr, h);
			c.lineTo(w - rr, h);
			c.quadTo(w, h, w, h - r);
			c.lineTo(w, h - footer);
		}
		else
		{
			// Divider falls inside the corners: trace the lane wall (radius r)
			// from where its quadratic crosses y = h - footer (split at t)
			var t = 1 - Math.sqrt(footer / r);
			var px = rr * t * t;
			var bx = rr * t;
			c.moveTo(px, h - footer);
			c.quadTo(bx, h, rr, h);
			c.lineTo(w - rr, h);
			c.quadTo(w - bx, h, w - px, h - footer);
		}
	}
	else
	{
		var rr = Math.min(h / 2, r);

		if (footer >= r)
		{
			c.moveTo(w - footer, 0);
			c.lineTo(w - r, 0);
			c.quadTo(w, 0, w, rr);
			c.lineTo(w, h - rr);
			c.quadTo(w, h, w - r, h);
			c.lineTo(w - footer, h);
		}
		else
		{
			var t = 1 - Math.sqrt(footer / r);
			var py = rr * t * t;
			var by = rr * t;
			c.moveTo(w - footer, py);
			c.quadTo(w, by, w, rr);
			c.lineTo(w, h - rr);
			c.quadTo(w, h - by, w - footer, h - py);
		}
	}

	c.close();

	if (fill != null && fill != mxConstants.NONE)
	{
		c.fillAndStroke();
	}
	else
	{
		c.stroke();
	}
};

/**
 * Function: paintDivider
 *
 * Paints the divider between swimlane title and content area.
 */
mxSwimlane.prototype.paintDivider = function(c, x, y, w, h, start, shadow)
{
	if (start != 0)
	{
		if (!shadow)
		{
			c.setShadow(false);
		}

		c.begin();
		
		if (this.isHorizontal())
		{
			c.moveTo(0, start);
			c.lineTo(w, start);
		}
		else
		{
			c.moveTo(start, 0);
			c.lineTo(start, h);
		}

		c.stroke();
	}
};

/**
 * Function: paintSeparator
 *
 * Paints the vertical or horizontal separator line between swimlanes.
 */
mxSwimlane.prototype.paintSeparator = function(c, x, y, w, h, start, color)
{
	if (color != mxConstants.NONE)
	{
		c.setStrokeColor(color);
		c.setDashed(true);
		c.begin();
		
		if (this.isHorizontal())
		{
			c.moveTo(w, start);
			c.lineTo(w, h);
		}
		else
		{
			c.moveTo(start, 0);
			c.lineTo(w, 0);
		}
		
		c.stroke();
		c.setDashed(false);
	}
};

/**
 * Function: getImageBounds
 *
 * Paints the swimlane vertex shape.
 */
mxSwimlane.prototype.getImageBounds = function(x, y, w, h)
{
	if (this.isHorizontal())
	{
		return new mxRectangle(x + w - this.imageSize, y, this.imageSize, this.imageSize);
	}
	else
	{
		return new mxRectangle(x, y, this.imageSize, this.imageSize);
	}
};
